package assets

import "github.com/TrebuchetDynamics/gormes-agent/internal/adapters/apiserver/assets/manifest"

// DashboardAssetsManifest describes the front-end scaffold that can be built by
// Vite and embedded by the Go dashboard shell. It is intentionally static for
// this slice: later rows can replace RequiredAssets with the actual build
// manifest after page behavior is implemented.
type DashboardAssetsManifest = manifest.DashboardAssetsManifest

// DashboardDistManifest returns the deterministic dashboard scaffold contract
// used by tests and by future server-embedding work.
func DashboardDistManifest() DashboardAssetsManifest {
	return manifest.DashboardDistManifest()
}

package assets

import "testing"

func TestDashboardDistManifest(t *testing.T) {
	manifest := DashboardDistManifest()
	if manifest.EntryHTML != "index.html" {
		t.Fatalf("entry html = %q, want index.html", manifest.EntryHTML)
	}
	if manifest.AppEntry != "src/main.tsx" {
		t.Fatalf("app entry = %q, want src/main.tsx", manifest.AppEntry)
	}
	wantRoutes := []string{"/", "/chat", "/config", "/env", "/sessions", "/logs", "/cron", "/skills", "/docs", "/analytics"}
	if len(manifest.Routes) != len(wantRoutes) {
		t.Fatalf("routes = %v, want %v", manifest.Routes, wantRoutes)
	}
	for i, want := range wantRoutes {
		if manifest.Routes[i] != want {
			t.Fatalf("route[%d] = %q, want %q", i, manifest.Routes[i], want)
		}
	}
	if len(manifest.RequiredAssets) == 0 {
		t.Fatal("required assets are empty")
	}
}

package assets

import (
	"net/http"

	"github.com/TrebuchetDynamics/gormes-agent/internal/adapters/apiserver/assets/staticfiles"
)

// StaticHandler serves embedded dashboard static assets under /static/.
func StaticHandler() http.Handler {
	return staticfiles.Handler()
}

package manifest

// DashboardAssetsManifest describes the front-end scaffold that can be built by
// Vite and embedded by the Go dashboard shell. It is intentionally static for
// this slice: later rows can replace RequiredAssets with the actual build
// manifest after page behavior is implemented.
type DashboardAssetsManifest struct {
	EntryHTML      string
	AppEntry       string
	Routes         []string
	RequiredAssets []string
}

// DashboardDistManifest returns the deterministic dashboard scaffold contract
// used by tests and by future server-embedding work.
func DashboardDistManifest() DashboardAssetsManifest {
	return DashboardAssetsManifest{
		EntryHTML: "index.html",
		AppEntry:  "src/main.tsx",
		Routes: []string{
			"/",
			"/chat",
			"/config",
			"/env",
			"/sessions",
			"/logs",
			"/cron",
			"/skills",
			"/docs",
			"/analytics",
		},
		RequiredAssets: []string{"web/package.json", "web/vite.config.ts", "web/src/App.tsx", "web/src/main.tsx"},
	}
}

package staticfiles

import (
	"embed"
	"io/fs"
	"net/http"
)

//go:embed static/*
var staticFS embed.FS

// Handler serves embedded dashboard static assets under /static/.
func Handler() http.Handler {
	sub, _ := fs.Sub(staticFS, "static")
	return http.StripPrefix("/static/", http.FileServer(http.FS(sub)))
}

